// parseHexColor parses a hex color string and returns a color.Color.
// Supports formats: 3, 4, 6, and 8 digit hex (with or without # prefix).
func parseHexColor(hex string) (color.Color, error) {
	hex = strings.TrimPrefix(hex, "#")

	var r, g, b, a uint8
	a = 0xff // default alpha

	switch len(hex) {
	case 3: // RGB
		if _, err := fmt.Sscanf(hex, "%1x%1x%1x", &r, &g, &b); err != nil {
			return color.Transparent, err
		}
		r = r*16 + r
		g = g*16 + g
		b = b*16 + b
	case 4: // RGBA
		if _, err := fmt.Sscanf(hex, "%1x%1x%1x%1x", &r, &g, &b, &a); err != nil {
			return color.Transparent, err
		}
		r = r*16 + r
		g = g*16 + g
		b = b*16 + b
		a = a*16 + a
	case 6: // RRGGBB
		if _, err := fmt.Sscanf(hex, "%02x%02x%02x", &r, &g, &b); err != nil {
			return color.Transparent, err
		}
	case 8: // RRGGBBAA
		if _, err := fmt.Sscanf(hex, "%02x%02x%02x%02x", &r, &g, &b, &a); err != nil {
			return color.Transparent, err
		}
	default:
		return color.Transparent, errors.New("invalid hex color format")
	}

	return color.NRGBA{R: r, G: g, B: b, A: a}, nil
}

// textStyleFromString converts a font style name to a TextStyle.
func textStyleFromString(name string) fyne.TextStyle {
	switch name {
	case "bold":
		return fyne.TextStyle{Bold: true}
	case "italic":
		return fyne.TextStyle{Italic: true}
	case "boldItalic":
		return fyne.TextStyle{Bold: true, Italic: true}
	case "monospace":
		return fyne.TextStyle{Monospace: true}
	case "regular":
		fallthrough
	default:
		return fyne.TextStyle{}
	}
}

