import (
	"fmt"

	"fyne.io/fyne/v2"
	"fyne.io/fyne/v2/storage"
)

// NewSprintf returns a String binding that formats its content using fmt.Sprintf.
// When any source binding changes, the formatted string is automatically updated.
// Set() parses the string back using fmt.Sscanf and updates source bindings.
//
// Since: 2.2
func NewSprintf(format string, bindings ...DataItem) String {
	s := &sprintfBinding{
		format:   format,
		bindings: bindings,
	}
	s.base = base{}

	// Add listeners to all source bindings
	for _, b := range bindings {
		b.AddListener(NewDataListener(func() {
			s.lock.Lock()
			s.cachedValue, s.lastError = s.getValue()
			s.lock.Unlock()
			s.trigger()
		}))
	}

	// Initialize cached value
	s.cachedValue, s.lastError = s.getValue()

	return s
}

type sprintfBinding struct {
	base
	format      string
	bindings    []DataItem
	cachedValue string
	lastError   error
}

func (s *sprintfBinding) Get() (string, error) {
	s.lock.RLock()
	defer s.lock.RUnlock()

	if s.lastError != nil {
		return "", s.lastError
	}
	return s.cachedValue, nil
}

func (s *sprintfBinding) Set(str string) error {
	values := make([]interface{}, len(s.bindings))
	ptrs := make([]interface{}, len(s.bindings))

	// Create pointers for Sscanf
	for i, b := range s.bindings {
		switch binding := b.(type) {
		case Bool:
			var v bool
			ptrs[i] = &v
			values[i] = &v
		case Bytes:
			// Bytes cannot be round-tripped
			return fmt.Errorf("cannot parse Bytes binding from string")
		case Float:
			var v float64
			ptrs[i] = &v
			values[i] = &v
		case Int:
			var v int
			ptrs[i] = &v
			values[i] = &v
		case Rune:
			var v rune
			ptrs[i] = &v
			values[i] = &v
		case String:
			var v string
			ptrs[i] = &v
			values[i] = &v
		case URI:
			var v string
			ptrs[i] = &v
			values[i] = &v
		default:
			return fmt.Errorf("unsupported binding type")
		}
	}

	// Parse the string
	n, err := fmt.Sscanf(str, s.format, ptrs...)
	if err != nil {
		return err
	}
	if n != len(s.bindings) {
		return errParseFailed
	}

	// Set each binding with the parsed value
	for i, b := range s.bindings {
		switch binding := b.(type) {
		case Bool:
			v := *values[i].(*bool)
			if err := binding.Set(v); err != nil {
				return err
			}
		case Float:
			v := *values[i].(*float64)
			if err := binding.Set(v); err != nil {
				return err
			}
		case Int:
			v := *values[i].(*int)
			if err := binding.Set(v); err != nil {
				return err
			}
		case Rune:
			v := *values[i].(*rune)
			if err := binding.Set(v); err != nil {
				return err
			}
		case String:
			v := *values[i].(*string)
			if err := binding.Set(v); err != nil {
				return err
			}
		case URI:
			v := *values[i].(*string)
			uri, err := storage.ParseURI(v)
			if err != nil {
				return err
			}
			if err := binding.Set(uri); err != nil {
				return err
			}
		}
	}

	return nil
}

func (s *sprintfBinding) getValue() (string, error) {
	values := make([]interface{}, len(s.bindings))

	for i, b := range s.bindings {
		var err error
		switch binding := b.(type) {
		case Bool:
			values[i], err = binding.Get()
		case Bytes:
			values[i], err = binding.Get()
		case Float:
			values[i], err = binding.Get()
		case Int:
			values[i], err = binding.Get()
		case Rune:
			values[i], err = binding.Get()
		case String:
			values[i], err = binding.Get()
		case URI:
			var u fyne.URI
			u, err = binding.Get()
			if err == nil {
				values[i] = u.String()
			}
		default:
			return "", fmt.Errorf("unsupported binding type")
		}

		if err != nil {
			return "", err
		}
	}

	return fmt.Sprintf(s.format, values...), nil
}

// StringToStringWithFormat wraps a String binding with a format string.
// If the format is "%s" (identity), returns the original binding.
//
// Since: 2.2
func StringToStringWithFormat(str String, format string) String {
	if format == "%s" {
		return str
	}
	return NewSprintf(format, str)
}

